import { ComponentProps, forwardRef } from "react";
import styles from "./card.module.less";
import { multipleClassNames } from "@/core/helpers";
import { MotionProps, motion } from "framer-motion";

type CardProps = Omit<ComponentProps<"div">, "onClick"> &
  MotionProps & {
    onClick?: (event: React.MouseEvent<HTMLDivElement> | React.KeyboardEvent<HTMLDivElement>) => void;
  };

const Card = forwardRef<HTMLDivElement, CardProps>(({ children, className, onClick, tabIndex, ...props }, ref) => {
  const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    // Handle Enter and Space keys for accessibility
    if (onClick && (event.key === "Enter" || event.key === " ")) {
      event.preventDefault();
      onClick(event); // Cast to satisfy TypeScript
    }
  };

  return (
    <motion.div
      ref={ref}
      className={multipleClassNames(styles.card, className)}
      onClick={onClick}
      onKeyDown={handleKeyDown}
      role={onClick ? "button" : undefined}
      tabIndex={tabIndex !== undefined ? tabIndex : onClick ? 0 : undefined}
      {...props}
    >
      {children}
    </motion.div>
  );
});

Card.displayName = "Card";

export default Card;
